// DFAI Granola webhook check (Standard Webhooks, HMAC-SHA256 in plain JavaScript).
// Generated from tools/n8n/sha256.ts, standard-webhook.ts and granola-webhook.ts
// in the DFAI repo by `pnpm n8n:build`:
// change those files and rebuild rather than editing here (except SECRET).

// sha256.ts
const { sha256, hmacSha256 } = (() => {
/*
 * SHA-256 and HMAC-SHA256 (FIPS 180-4, RFC 2104) in plain JavaScript, for
 * the Granola webhook's signature check. Compiled into an n8n Code node, it
 * needs neither `require('crypto')` nor the Crypto node, whichever of them
 * n8n Cloud's sandbox allows (ADR-0034's spike), nor Buffer or TextEncoder.
 */
const ROUND_CONSTANTS = Uint32Array.of(0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2);
const INITIAL_HASH = Uint32Array.of(0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19);
/** An element of a fixed-length array; every index used here is in range. */
const at = (words, index) => words[index] ?? 0;
const rotateRight = (word, by) => (word >>> by) | (word << (32 - by));
/** The message, padded to whole 64-byte blocks and ending in its length in bits. */
function padded(message) {
    const blocks = Math.ceil((message.length + 9) / 64);
    const bytes = new Uint8Array(blocks * 64);
    bytes.set(message);
    bytes[message.length] = 0x80;
    const view = new DataView(bytes.buffer);
    const bits = message.length * 8;
    view.setUint32(bytes.length - 8, Math.floor(bits / 2 ** 32));
    view.setUint32(bytes.length - 4, bits >>> 0);
    return view;
}
/** The message schedule for the block at `offset`. */
function schedule(view, offset, words) {
    for (let i = 0; i < 16; i += 1)
        words[i] = view.getUint32(offset + i * 4);
    for (let i = 16; i < 64; i += 1) {
        const early = at(words, i - 15);
        const late = at(words, i - 2);
        const sigma0 = rotateRight(early, 7) ^ rotateRight(early, 18) ^ (early >>> 3);
        const sigma1 = rotateRight(late, 17) ^ rotateRight(late, 19) ^ (late >>> 10);
        words[i] = (at(words, i - 16) + sigma0 + at(words, i - 7) + sigma1) >>> 0;
    }
}
/** One block folded into `hash`: the 64 rounds over the eight working words. */
function compress(hash, words) {
    // The hash is always eight words.
    let [a, b, c, d, e, f, g, h] = Array.from(hash);
    for (let i = 0; i < 64; i += 1) {
        const sum1 = rotateRight(e, 6) ^ rotateRight(e, 11) ^ rotateRight(e, 25);
        const choice = (e & f) ^ (~e & g);
        const first = (h + sum1 + choice + at(ROUND_CONSTANTS, i) + at(words, i)) >>> 0;
        const sum0 = rotateRight(a, 2) ^ rotateRight(a, 13) ^ rotateRight(a, 22);
        const second = (sum0 + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
        [h, g, f, e, d, c, b, a] = [g, f, e, (d + first) >>> 0, c, b, a, (first + second) >>> 0];
    }
    [a, b, c, d, e, f, g, h].forEach((word, n) => {
        hash[n] = at(hash, n) + word;
    });
}
function sha256(message) {
    const view = padded(message);
    const hash = Uint32Array.from(INITIAL_HASH);
    const words = new Uint32Array(64);
    for (let offset = 0; offset < view.byteLength; offset += 64) {
        schedule(view, offset, words);
        compress(hash, words);
    }
    const digest = new DataView(new ArrayBuffer(32));
    hash.forEach((word, n) => digest.setUint32(n * 4, word));
    return new Uint8Array(digest.buffer);
}
const BLOCK = 64;
/** HMAC-SHA256 of `message` under `key` (RFC 2104). */
function hmacSha256(key, message) {
    const block = new Uint8Array(BLOCK);
    block.set(key.length > BLOCK ? sha256(key) : key);
    const inner = new Uint8Array(BLOCK + message.length);
    const outer = new Uint8Array(BLOCK + 32);
    for (let i = 0; i < BLOCK; i += 1) {
        inner[i] = at(block, i) ^ 0x36;
        outer[i] = at(block, i) ^ 0x5c;
    }
    inner.set(message, BLOCK);
    outer.set(sha256(inner), BLOCK);
    return sha256(outer);
}
return { sha256, hmacSha256 };
})();

// standard-webhook.ts
const { WebhookRefusal, TIMESTAMP_TOLERANCE_SECONDS, base64Bytes, base64Text, utf8Bytes, utf8Text, verifyStandardWebhook } = (() => {
/*
 * The Standard Webhooks signature check (standardwebhooks.com, "Verifying
 * webhook authenticity"), which Granola signs its webhooks with (ADR-0034).
 * Plain JavaScript like sha256.ts, so the compiled Code node runs on any
 * engine: no Buffer, atob, TextEncoder or crypto.
 */
/** Why a webhook was refused. The workflow answers it with a 401, which Granola does not retry. */
class WebhookRefusal extends Error {
    name = 'WebhookRefusal';
}
/** How far a webhook's timestamp may be from now, either way, in seconds (the spec's five minutes). */
const TIMESTAMP_TOLERANCE_SECONDS = 5 * 60;
const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const BASE64_TEXT = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;
/** Standard base64 as bytes; null when it is not base64. */
function base64Bytes(text) {
    if (!BASE64_TEXT.test(text))
        return null;
    const digits = text.replace(/=+$/, '');
    const bytes = new Uint8Array(Math.floor((digits.length * 3) / 4));
    let bits = 0;
    let held = 0;
    let next = 0;
    for (const digit of digits) {
        held = (held << 6) | BASE64.indexOf(digit);
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            bytes[next] = (held >> bits) & 0xff;
            next += 1;
        }
    }
    return bytes;
}
function base64Text(bytes) {
    let text = '';
    for (let i = 0; i < bytes.length; i += 3) {
        const chunk = ((bytes[i] ?? 0) << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0);
        const digits = [18, 12, 6, 0].map((shift) => BASE64.charAt((chunk >> shift) & 63)).join('');
        // One byte gives two digits, two give three, three give four.
        text += digits.slice(0, Math.min(3, bytes.length - i) + 1);
    }
    return text.padEnd(Math.ceil(bytes.length / 3) * 4, '=');
}
/** Text as UTF-8 bytes (a lone surrogate as U+FFFD, as TextEncoder writes it). */
function utf8Bytes(text) {
    const bytes = [];
    for (const each of text) {
        let point = each.codePointAt(0) ?? 0;
        if (point >= 0xd800 && point <= 0xdfff)
            point = 0xfffd;
        if (point < 0x80)
            bytes.push(point);
        else if (point < 0x800)
            bytes.push(0xc0 | (point >> 6), 0x80 | (point & 63));
        else if (point < 0x10000) {
            bytes.push(0xe0 | (point >> 12), 0x80 | ((point >> 6) & 63), 0x80 | (point & 63));
        }
        else {
            bytes.push(0xf0 | (point >> 18), 0x80 | ((point >> 12) & 63), 0x80 | ((point >> 6) & 63), 0x80 | (point & 63));
        }
    }
    return Uint8Array.from(bytes);
}
/** The length of the sequence a lead byte starts; 0 for a byte no UTF-8 sequence starts with. */
function sequenceLength(lead) {
    if (lead < 0x80)
        return 1;
    if (lead < 0xc2)
        return 0; // a continuation byte, or C0/C1, which only start overlong forms
    if (lead < 0xe0)
        return 2;
    if (lead < 0xf0)
        return 3;
    // F5 and up decode past U+10FFFF (F8 and up to an overlong form): `holds` refuses them.
    return 4;
}
/** The smallest point each length may hold: anything less is an overlong form. */
const SMALLEST = [0, 0, 0x80, 0x800, 0x10000];
/** Whether a decoded point is one this length may hold: not overlong, not a surrogate, not past U+10FFFF. */
const holds = (point, length) => point >= (SMALLEST[length] ?? 0) && point <= 0x10ffff && (point < 0xd800 || point > 0xdfff);
/**
 * UTF-8 bytes as text (RFC 3629); refused when they are not UTF-8 — a
 * stray or missing continuation, an overlong form, an encoded surrogate or a
 * point past U+10FFFF — since a signed body that is not text is not Granola's.
 */
function utf8Text(bytes) {
    let text = '';
    for (let i = 0; i < bytes.length;) {
        const lead = bytes[i] ?? 0;
        const length = sequenceLength(lead);
        if (length === 0 || i + length > bytes.length)
            throw new WebhookRefusal('body: not UTF-8');
        let point = length === 1 ? lead : lead & (0xff >> (length + 1));
        for (let k = 1; k < length; k += 1) {
            const trail = bytes[i + k] ?? 0;
            if ((trail & 0xc0) !== 0x80)
                throw new WebhookRefusal('body: not UTF-8');
            point = (point << 6) | (trail & 63);
        }
        if (!holds(point, length))
            throw new WebhookRefusal('body: not UTF-8');
        text += String.fromCodePoint(point);
        i += length;
    }
    return text;
}
/** Whether two strings are equal, in a time that does not tell how much of them matched. */
function sameText(a, b) {
    let difference = a.length ^ b.length;
    for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
        difference |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
    }
    return difference === 0;
}
/** The signing key: the secret's base64 after `whsec_`. */
function signingKey(secret) {
    const key = secret.startsWith('whsec_') ? base64Bytes(secret.slice('whsec_'.length)) : null;
    if (key === null || key.length === 0) {
        throw new WebhookRefusal('the webhook secret is not set (paste whsec_… from Granola)');
    }
    return key;
}
/** A header as n8n's Webhook node hands it over (names lower-case); null when absent. */
function header(headers, name) {
    if (typeof headers !== 'object' || headers === null)
        return null;
    const value = headers[name];
    return typeof value === 'string' ? value : null;
}
/** The webhook's timestamp, refused when it is not one or is more than the tolerance from now. */
function freshTimestamp(value, now) {
    if (value === null || !/^\d{1,12}$/.test(value)) {
        throw new WebhookRefusal('webhook-timestamp: missing or not seconds since the epoch');
    }
    // A clock that is not a number would make every distance NaN, and no NaN is "too far".
    if (!Number.isFinite(now))
        throw new WebhookRefusal('the clock is not a number; refusing');
    if (Math.abs(now / 1000 - Number(value)) > TIMESTAMP_TOLERANCE_SECONDS) {
        throw new WebhookRefusal('webhook-timestamp: more than five minutes from now');
    }
    return value;
}
/**
 * Checks a delivery's signature: HMAC-SHA256 of `{id}.{timestamp}.{body}`
 * under the secret's key, base64, matching one of the `v1,` signatures in
 * `webhook-signature` (space-separated, for key rotation). Returns the
 * webhook's id; throws {@link WebhookRefusal} for anything else.
 */
function verifyStandardWebhook(delivery, check) {
    const key = signingKey(check.secret);
    const id = header(delivery.headers, 'webhook-id');
    if (id === null || id === '')
        throw new WebhookRefusal('webhook-id: missing');
    const timestamp = freshTimestamp(header(delivery.headers, 'webhook-timestamp'), check.now);
    const signed = utf8Bytes(`${id}.${timestamp}.`);
    const message = new Uint8Array(signed.length + delivery.body.length);
    message.set(signed);
    message.set(delivery.body, signed.length);
    const expected = base64Text(hmacSha256(key, message));
    const offered = (header(delivery.headers, 'webhook-signature') ?? '').split(' ');
    const matches = offered.filter((each) => each.startsWith('v1,'));
    if (!matches.some((each) => sameText(each.slice('v1,'.length), expected))) {
        throw new WebhookRefusal('webhook-signature: no v1 signature matches');
    }
    return id;
}
return { WebhookRefusal, TIMESTAMP_TOLERANCE_SECONDS, base64Bytes, base64Text, utf8Bytes, utf8Text, verifyStandardWebhook };
})();

// granola-webhook.ts
const { webhookNoteId, MAX_BODY_BYTES, UnreadableWebhookBody, bodyExcerpt, verifyGranolaWebhook } = (() => {
/*
 * A Granola webhook (ADR-0034): signed by Standard Webhooks, carrying only
 * the note's id. Compiled into the workflow's "Verify Granola signature"
 * Code node (granola-code-node.ts); the note is fetched only after this.
 */
/** A Granola note id as the API writes it (`not_4kTq2mWxLp4Rz7`): it goes into the fetch's URL path. */
const NOTE_ID = /^[A-Za-z0-9_-]{1,64}$/;
const isRecord = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);
/**
 * The note id a verified body names: `note_id` at the top or under `data`.
 * Granola's docs say only that the payload carries a `note_id`, not where,
 * so both are read (tools/n8n/README.md, "Granola webhooks → DFAI").
 */
function webhookNoteId(body) {
    let payload;
    try {
        payload = JSON.parse(body);
    }
    catch {
        throw new WebhookRefusal('body: not JSON');
    }
    const data = isRecord(payload) ? payload['data'] : undefined;
    const id = isRecord(payload)
        ? (payload['note_id'] ?? (isRecord(data) ? data['note_id'] : null))
        : null;
    if (typeof id !== 'string' || !NOTE_ID.test(id)) {
        throw new WebhookRefusal('body: no note_id that is a Granola note id');
    }
    return id;
}
/**
 * The most a delivery's body may be, checked before it is hashed. Granola's
 * payload carries only a note id; anything near this is not Granola's.
 */
const MAX_BODY_BYTES = 64 * 1024;
/** How much of an unreadable body the failure email quotes. */
const EXCERPT_BYTES = 200;
/**
 * A delivery Granola signed whose body cannot be read: it is answered 200
 * and emailed, never refused, since the sender is Granola (ADR-0034).
 */
class UnreadableWebhookBody extends Error {
    name = 'UnreadableWebhookBody';
}
/** The body's first bytes, printable ASCII kept and every other byte as `\xNN`: safe in an email. */
function bodyExcerpt(body) {
    let text = '';
    for (const byte of body.subarray(0, EXCERPT_BYTES)) {
        text +=
            byte >= 0x20 && byte < 0x7f
                ? String.fromCharCode(byte)
                : `\\x${byte.toString(16).padStart(2, '0')}`;
    }
    return body.length > EXCERPT_BYTES ? `${text}…` : text;
}
/** The delivery's signature, held to the size cap first: a refusal is an answer, not a failure. */
function signature(delivery, check) {
    try {
        if (delivery.body.length > MAX_BODY_BYTES) {
            throw new WebhookRefusal(`body: over ${MAX_BODY_BYTES} bytes`);
        }
        return verifyStandardWebhook(delivery, check);
    }
    catch (error) {
        if (error instanceof WebhookRefusal)
            return { signed: false, reason: error.message };
        throw error;
    }
}
/**
 * A delivery checked, then read: the body's note id is trusted only once its
 * signature is. A refusal comes back as `signed: false` (the workflow answers
 * it 401, in silence); a signed body that names no note throws
 * {@link UnreadableWebhookBody}; anything else that throws is a fault.
 */
function verifyGranolaWebhook(delivery, check) {
    const webhookId = signature(delivery, check);
    if (typeof webhookId !== 'string')
        return webhookId;
    try {
        return { signed: true, webhookId, noteId: webhookNoteId(utf8Text(delivery.body)) };
    }
    catch (error) {
        if (!(error instanceof WebhookRefusal))
            throw error;
        throw new UnreadableWebhookBody(`signed by Granola, but ${error.message}; it begins: ${bodyExcerpt(delivery.body)}`);
    }
}
return { webhookNoteId, MAX_BODY_BYTES, UnreadableWebhookBody, bodyExcerpt, verifyGranolaWebhook };
})();

// --- n8n ---
// SECRET: Granola → Settings → Connectors → Webhooks → your endpoint’s signing secret.
// Paste it here in n8n only. Never commit it, and never export this workflow with it in.
const SECRET = "whsec_PASTE_THE_SECRET_FROM_GRANOLA_HERE";
const body = new Uint8Array(await this.helpers.getBinaryDataBuffer(0, "data"));
const delivery = { headers: $input.first().json.headers, body };
// A refusal leaves as { signed: false } (answered 401); an unreadable signed body, or any
// fault here (no raw body), throws to the error output: answered 200 and emailed.
return [{ json: verifyGranolaWebhook(delivery, { secret: SECRET, now: Date.now() }) }];

// DFAI meeting mapper (meeting-import contract v1).
// Generated from packages/domain/src/meetings/mapping/*.ts and tools/n8n/*.ts
// in the DFAI repo by `pnpm n8n:build`:
// change those files and rebuild rather than editing here.

// meeting-mapping-error.ts
const { MeetingMappingError, shown, oneLine } = (() => {
/**
 * A meeting the mapping cannot turn into a contract file (a required field is
 * missing or unreadable), or one the workflow cannot safely write. In n8n the
 * Code node sends the item out of its error output to "DFAI commit failed",
 * which emails this message, and the run goes on; `POST /v1/meetings` answers
 * it as `invalid`, with this message.
 */
class MeetingMappingError extends Error {
    name = 'MeetingMappingError';
}
/** How much of a value a refusal shows: enough to find it, never a meeting's content. */
const SHOWN_LENGTH = 40;
/**
 * A value as a refusal may show it: text quoted and cut to
 * {@link SHOWN_LENGTH} characters, anything else by its type alone. A refusal
 * is emailed by n8n and logged by the pull, so it never carries what the
 * value holds.
 */
function shown(value) {
    if (typeof value !== 'string')
        return Array.isArray(value) ? 'a list' : String(typeof value);
    const characters = [...value];
    const cut = characters.length > SHOWN_LENGTH;
    return JSON.stringify(cut ? `${characters.slice(0, SHOWN_LENGTH).join('')}…` : value);
}
/**
 * The value as trimmed text with its whitespace collapsed; '' when there is
 * none. Refuses an object, naming `field` (and never what the object holds).
 */
function oneLine(value, field) {
    if (value === null || value === undefined)
        return '';
    if (Array.isArray(value)) {
        return value
            .map((each) => oneLine(each, field))
            .filter(Boolean)
            .join(', ');
    }
    if (typeof value === 'object') {
        const named = field === undefined ? '' : `${field}: `;
        throw new MeetingMappingError(`${named}expected text, got object`);
    }
    return (String(value)
        // Control characters have no place in a one-line value, and YAML refuses some.
        .replace(/\p{Cc}/gu, ' ')
        .replace(/\s+/g, ' ')
        .trim());
}
return { MeetingMappingError, shown, oneLine };
})();

// meeting-instant.ts
const { rfc3339Instant } = (() => {
/*
 * An RFC 3339 instant read by our own rules rather than `Date.parse`, whose
 * reading of anything past the ECMAScript date format is the engine's: the
 * app's webview (JavaScriptCore) and n8n (V8) answer differently for a
 * lowercase `t`/`z`, a 60th second, or 30 February. Two writers of one note
 * must write the same bytes, so neither engine is asked.
 */
/** `date-time` of RFC 3339 §5.6; `T` and `Z` in either case, as §5.6 allows. */
const RFC_3339 = /^(\d{4})-(\d{2})-(\d{2})[Tt](\d{2}):(\d{2}):(\d{2})(?:\.(\d+))?(?:[Zz]|([+-])(\d{2}):(\d{2}))$/;
const DAY_MS = 24 * 60 * 60_000;
const isLeapYear = (year) => (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
/** How many days the month has in the year: 28 to 31, 29 for February in a leap year. */
function daysIn(year, month) {
    if (month === 2)
        return isLeapYear(year) ? 29 : 28;
    return [4, 6, 9, 11].includes(month) ? 30 : 31;
}
/**
 * Days from 1970-01-01 to a day of the proleptic Gregorian calendar, by
 * arithmetic alone (H. Hinnant's days_from_civil): `Date.UTC` would read a
 * year under 100 as 19xx.
 */
function daysFromEpoch(year, month, day) {
    const y = month <= 2 ? year - 1 : year;
    const era = Math.floor(y / 400);
    const yearOfEra = y - era * 400;
    const dayOfYear = Math.floor((153 * (month + (month > 2 ? -3 : 9)) + 2) / 5) + day - 1;
    const dayOfEra = yearOfEra * 365 + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100) + dayOfYear;
    return era * 146_097 + dayOfEra - 719_468;
}
/**
 * Milliseconds since the epoch for an RFC 3339 instant, or null when the
 * text is not one. Every field is held to its range: a month of 01–12, a day
 * the month has in that year (29 February only in a leap year), hours 00–23,
 * minutes 00–59, an offset of at most 23:59. Seconds are 00–59: a leap second
 * (`:60`, which §5.6 allows) is refused rather than clamped, since JavaScript
 * time has no leap seconds and Granola sends none. A fraction is cut, never
 * rounded, to the millisecond. An instant with no offset is not one.
 */
function rfc3339Instant(text) {
    const match = RFC_3339.exec(text);
    if (match === null)
        return null;
    const at = (group) => Number(match[group] ?? '0');
    const [year, month, day, hour, minute, second] = [at(1), at(2), at(3), at(4), at(5), at(6)];
    const [offsetHours, offsetMinutes] = [at(9), at(10)];
    if (month < 1 || month > 12 || day < 1 || day > daysIn(year, month))
        return null;
    if (hour > 23 || minute > 59 || second > 59)
        return null;
    if (offsetHours > 23 || offsetMinutes > 59)
        return null;
    const millis = Number((match[7] ?? '').padEnd(3, '0').slice(0, 3));
    const timeOfDay = ((hour * 60 + minute) * 60 + second) * 1000;
    const east = (match[8] === '-' ? -1 : 1) * (offsetHours * 60 + offsetMinutes);
    return daysFromEpoch(year, month, day) * DAY_MS + timeOfDay + millis - east * 60_000;
}
return { rfc3339Instant };
})();

// meeting-stated.ts
const { zoneOffsetMinutes, readStated } = (() => {
const MONTHS = [
    'january',
    'february',
    'march',
    'april',
    'may',
    'june',
    'july',
    'august',
    'september',
    'october',
    'november',
    'december',
];
/**
 * A day as an email or a Gemini doc title writes it — `Oct 6, 2026`,
